    "target_description": "A subsequent agent action intended to verify or validate the correctness of that artifact."
  },
  {
    "name": "CORROBORATES_PRIOR_OBSERVATION",
    "definition": "A later execution observation reports a condition that is consistent with and confirms a condition already reported by an earlier observation.",
    "source_description": "An earlier observation reporting a missing resource or environmental condition.",
    "target_description": "A later observation reporting a consistent condition or consequent failure that confirms the earlier observation."
  },
  {
    "name": "ATTEMPTS_TO_REPAIR_FAILURE",
    "definition": "A subsequent agent action attempts to resolve a failure or missing prerequisite that was identified during an earlier execution step.",
    "source_description": "An earlier observed execution failure, such as a required command, dependency, or resource being unavailable.",
    "target_description": "A subsequent agent action intended to resolve that failure by establishing the missing prerequisite."
  },
  {
    "name": "USES_DIAGNOSTIC_OBSERVATION_TO_SELECT_ACTION",
    "definition": "A diagnostic observation about the execution environment or system state is used to determine which subsequent command or action is appropriate.",
    "source_description": "A diagnostic observation about the execution environment or system state.",
    "target_description": "A subsequently selected action chosen based on that diagnostic observation."
  },
  {
    "name": "DECLARES_COMPLETION_BASED_ON_VERIFIED_RESULTS",
    "definition": "A final completion decision is asserted and grounded in previously verified successful execution results and validated output artifacts.",
    "source_description": "A set of previously verified successful results and validated output artifacts.",
    "target_description": "A subsequent agent declaration that the task is complete and ready for grading."
  },
  {
    "name": "INVESTIGATES_FAILURE_CAUSE",
    "definition": "An execution failure whose cause is not yet understood is followed by a diagnostic action that inspects environment or tool state (e.g., versions, logs, installed packages) in order to explain the failure before attempting a repair.",
    "source_description": "An earlier observed execution failure whose cause is not yet understood.",
    "target_description": "A subsequent diagnostic action that inspects environment or tool state to determine the cause of the failure."
  },
  {
    "name": "VERIFIES_DEPENDENCY_AVAILABILITY_BEFORE_USE",
    "definition": "An agent decision to rely on a particular library, package, or tool is followed by an explicit check that the dependency is actually installed and available in the environment before it is used.",
    "source_description": "An agent decision to use a particular library, package, or tool as part of the plan.",
    "target_description": "A subsequent query that confirms whether that dependency is present in the environment."
  },
  {
    "name": "MONITORS_ASYNC_LONG_RUNNING_OPERATION",
    "definition": "An action that launches a long-running or background operation (such as a package build or installation) is followed by a separate action that waits for and inspects the progress or completion status of that operation.",
    "source_description": "An agent action that starts a long-running or background operation.",
    "target_description": "A subsequent action that polls or inspects the status or output of that operation."
  },
  {
    "name": "ENABLES_SUBSEQUENT_TOOL_USE",
    "definition": "A subsequent agent action relies on a tool, library, or capability that became available as the result of an earlier successful setup, installation, or environment-preparation step.",
    "source_description": "An earlier execution observation confirming that a required tool, library, or capability has been successfully installed or otherwise made available.",
    "target_description": "A subsequent agent action that invokes or relies on that now-available tool, library, or capability."
  },
  {
    "name": "INVESTIGATES_INCONSISTENCY_FROM_RESULT",
    "definition": "A subsequent diagnostic or investigative action is performed in response to an earlier execution result that reveals conflicting, ambiguous, or inconsistent evidence, in order to resolve the inconsistency.",
    "source_description": "An earlier execution result or observation that reveals conflicting, ambiguous, or inconsistent evidence.",
    "target_description": "A subsequent diagnostic or investigative action intended to resolve that inconsistency."
  },
  {
    "name": "SELECTS_CANDIDATE_FROM_EVALUATION",
    "definition": "A subsequent agent decision or action adopts one among multiple candidate alternatives based on the outcome of an earlier evaluation, scoring, or comparison of those alternatives.",
    "source_description": "An earlier execution result that evaluates, scores, or compares candidate alternatives.",
    "target_description": "A subsequent agent decision or action that adopts the selected alternative."
  },
  {
    "name": "IDENTIFIES_TRANSFORMATION_WEAKNESS_FROM_OBSERVATION",
    "definition": "An agent recognizes a specific weakness, limitation, or discrepancy in the behavior of a target transformation or processing mechanism by observing its implementation or execution, enabling subsequent construction of content that exploits it.",
    "source_description": "An observation of the target transformation's implementation or execution behavior that reveals how it processes content.",
    "target_description": "The agent's conclusion identifying a specific exploitable weakness or discrepancy in that transformation."
  },
  {
    "name": "DESIGNS_CANDIDATE_TO_EVADE_TRANSFORMATION",
    "definition": "An agent creates a candidate artifact that is deliberately constructed, based on previously observed transformation logic, so that it survives or bypasses the target transformation.",
    "source_description": "An earlier observation of the target transformation's logic or of its effect on content.",
    "target_description": "A subsequent agent action that creates a candidate artifact intended to bypass the transformation."
  },
  {
    "name": "DERIVES_SUCCESS_CRITERIA_FROM_VERIFICATION_SCRIPT",
    "definition": "An agent inspects a test or verification script to determine the conditions under which the task will be judged successful, and uses that understanding to guide subsequent solution construction.",
    "source_description": "An observation of a verification or test script that defines how the solution will be evaluated.",
    "target_description": "A subsequent agent action or solution strategy aimed at satisfying the identified success criteria."
  },
  {
    "name": "EXPERIMENTAL_RESULT_CONFIRMS_CANDIDATE_SOLUTION",
    "definition": "An observed result from testing a candidate approach provides evidence that the candidate satisfies a required condition, leading the agent to adopt or apply it as the solution.",
    "source_description": "An observation from a test, probe, or experiment performed on a candidate approach.",
    "target_description": "A subsequent agent decision or action that adopts or applies the candidate approach to the task."
  },
  {
    "name": "SILENT_FAILURE_CAUSES_DOWNSTREAM_FAILURE",
    "definition": "An earlier action's failure that produced no visible error indication causes a later observable execution failure.",
    "source_description": "An earlier execution step whose failure was suppressed or not surfaced as an error.",
    "target_description": "A later observed execution failure attributable to that earlier silent failure."
  },
  {
    "name": "REISSUES_ACTION_IN_RESPONSE_TO_CONFIRMATION_REQUEST",
    "definition": "A subsequent agent action repeats a previously issued operation because a tool observation withheld execution and explicitly requested confirmation or re-submission of that operation.",
    "source_description": "A tool observation that declines to execute a pending action and asks the agent to confirm or repeat the request.",
    "target_description": "A subsequent agent action that re-invokes the same pending operation to satisfy the confirmation request."
  },
  {
    "name": "RUNS_BROADER_TEST_SUITE_AFTER_VERIFICATION",
    "definition": "A successful targeted verification of the primary use case is followed by execution of a broader automated test suite, in order to check overall functionality beyond the specific case that was just verified.",
    "source_description": "A successful targeted verification confirming that the primary use case works as intended.",
    "target_description": "A subsequent execution of a broader automated test suite covering additional functionality."
  }
]

Review every edge type in the registry and assign exactly one revision operation.

Apply the supplied granularity rules and positive and negative examples when interpreting the human feedback.

Return the complete revision plan using the required JSON schema.
